create or replace function public.match_lead(target_lead_id uuid,result_limit integer default 5) returns table(business_id uuid,match_score numeric(5,2)) language plpgsql security definer set search_path=public as $$ declare v_lead public.leads%rowtype; v_plan public.project_plans%rowtype; v_limit integer:=greatest(1,least(coalesce(result_limit,5),10)); begin select * into v_lead from public.leads where id=target_lead_id; if v_lead.id is null then raise exception 'Lead not found'; end if; if coalesce(v_lead.homeowner_id,'00000000-0000-0000-0000-000000000000'::uuid)<>(select auth.uid()) and not public.is_admin() then raise exception 'Not authorized to match this lead'; end if; if v_lead.project_plan_id is null then raise exception 'Lead has no project plan to match'; end if; select * into v_plan from public.project_plans where id=v_lead.project_plan_id; if v_plan.id is null then raise exception 'Project plan not found'; end if; delete from public.lead_matches where lead_id=target_lead_id and match_status='pending'; return query with plan_categories as (select ppc.category_id from public.project_plan_categories ppc where ppc.plan_id=v_plan.id union select v_plan.category_id where v_plan.category_id is not null), candidates as (select b.id,(case when exists(select 1 from public.business_services bs join public.services s on s.id=bs.service_id join plan_categories pc on pc.category_id=s.category_id where bs.business_id=b.id) then 30 else 0 end + case when v_plan.city_id is not null and (exists(select 1 from public.business_service_areas bsa where bsa.business_id=b.id and bsa.city_id=v_plan.city_id) or b.city=(select c.name from public.cities c where c.id=v_plan.city_id)) then 25 else 0 end + case when exists(select 1 from public.business_services bs join public.services s on s.id=bs.service_id join plan_categories pc on pc.category_id=s.category_id where bs.business_id=b.id) then 20 else 0 end + case when v_plan.category_id is not null and exists(select 1 from public.business_services bs join public.services s on s.id=bs.service_id where bs.business_id=b.id and s.category_id=v_plan.category_id) then 15 else 0 end + case when b.status='active' and b.verification_status='verified' and exists(select 1 from public.business_profiles bp where bp.business_id=b.id and coalesce(nullif(trim(bp.about),''),'')<>'') then 10 when b.status='active' and b.verification_status='verified' then 8 when b.status='active' then 5 else 0 end)::numeric(5,2) as score from public.businesses b where b.status='active'), ranked as (select id,score from candidates where score>0 order by score desc,id limit v_limit), inserted as (insert into public.lead_matches(lead_id,business_id,match_score,match_status) select target_lead_id,r.id,r.score,'pending'::public.match_status from ranked r on conflict(lead_id,business_id) do update set match_score=excluded.match_score,match_status='pending',updated_at=now() returning business_id,match_score) select i.business_id,i.match_score from inserted i; if exists(select 1 from public.lead_matches where lead_id=target_lead_id) then update public.leads set status='matched',updated_at=now() where id=target_lead_id; update public.project_plans set status='matched',updated_at=now() where id=v_plan.id; insert into public.lead_events(lead_id,business_id,actor_id,event_type,metadata) select target_lead_id,lm.business_id,(select auth.uid()),'matched',jsonb_build_object('match_score',lm.match_score) from public.lead_matches lm where lm.lead_id=target_lead_id and lm.match_status='pending'; end if; end; $$; create or replace function public.submit_project_lead(plan_id uuid,contact_name text,contact_email text,contact_phone text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=(select auth.uid()); v_lead_id uuid; begin if v_uid is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.project_plans where id=plan_id and user_id=v_uid) then raise exception 'Project plan not found'; end if; insert into public.leads(project_plan_id,homeowner_id,contact_name,contact_email,contact_phone,status,source) values(plan_id,v_uid,nullif(trim(contact_name),''),nullif(trim(contact_email),''),nullif(trim(contact_phone),''),'new','planner') returning id into v_lead_id; insert into public.lead_events(lead_id,actor_id,event_type,metadata) values(v_lead_id,v_uid,'created',jsonb_build_object('source','planner')); perform public.match_lead(v_lead_id,5); return v_lead_id; end; $$; revoke all on function public.match_lead(uuid,integer) from public; grant execute on function public.match_lead(uuid,integer) to authenticated; revoke all on function public.submit_project_lead(uuid,text,text,text) from public; grant execute on function public.submit_project_lead(uuid,text,text,text) to authenticated;